namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public static class RecipeStore
{
    private static readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, Fresh mozzarella, San Marzano tomatoes, Fresh basil, Olive oil, Salt", Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Add torn mozzarella pieces.\n5. Bake 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle olive oil." },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper", Steps = "1. Cook spaghetti in salted water.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated Pecorino.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, stir in egg mixture.\n6. Season with black pepper and serve." },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Cream, Onion, Garlic, Ginger", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and garam masala.\n5. Simmer 15 minutes, add cream.\n6. Add chicken pieces and serve with rice." },
        new Recipe { Id = 4, Title = "Vegetable Samosas", Category = "Indian", Ingredients = "Potatoes, Peas, Cumin, Coriander, Flour, Ghee, Green chili", Steps = "1. Boil and mash potatoes.\n2. Mix with peas, cumin, coriander, and chili.\n3. Make dough with flour and ghee.\n4. Roll into circles, cut in half.\n5. Form cones, fill with potato mixture.\n6. Deep fry until golden brown." },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheddar cheese, Sour cream, Taco seasoning", Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water.\n3. Simmer until thickened.\n4. Warm taco shells.\n5. Fill with beef, lettuce, tomato, and cheese.\n6. Top with sour cream." },
        new Recipe { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime juice, Red onion, Cilantro, Jalapeño, Tomato, Salt", Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Dice onion, tomato, and jalapeño.\n4. Mix all ingredients together.\n5. Add lime juice and salt to taste.\n6. Serve with tortilla chips." },
        new Recipe { Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate, Butter, Eggs, Sugar, Flour, Vanilla extract", Steps = "1. Melt chocolate and butter together.\n2. Whisk eggs and sugar until fluffy.\n3. Fold chocolate mixture into eggs.\n4. Add flour and vanilla.\n5. Pour into greased ramekins.\n6. Bake at 425°F for 12 minutes. Center should be soft." },
        new Recipe { Id = 8, Title = "Miso Ramen", Category = "Japanese", Ingredients = "Ramen noodles, Miso paste, Pork belly, Soft-boiled egg, Green onion, Nori, Chicken broth", Steps = "1. Simmer chicken broth with miso paste.\n2. Sear sliced pork belly until caramelized.\n3. Cook ramen noodles per package directions.\n4. Prepare soft-boiled eggs (6.5 minutes).\n5. Assemble: noodles, broth, pork, halved egg.\n6. Garnish with green onion and nori." },
    };

    private static readonly Dictionary<int, List<int>> _ratings = new();

    public static IReadOnlyList<Recipe> GetAll() => _recipes.AsReadOnly();

    public static IEnumerable<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase));

    public static Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public static IEnumerable<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct();

    public static void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public static void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;
        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);

        var recipe = GetById(recipeId);
        if (recipe != null)
        {
            recipe.RatingCount = _ratings[recipeId].Count;
            recipe.AverageRating = _ratings[recipeId].Average();
        }
    }
}

@page "/recipes"
@page "/recipes/{Category}"
@using RecipeCommunity.Models

<PageTitle>Browse Recipes</PageTitle>

<h1>@(string.IsNullOrEmpty(Category) ? "All Recipes" : $"{Category} Recipes")</h1>

<div class="row mt-3">
    @foreach (var recipe in GetRecipes())
    {
        <div class="col-md-6 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@recipe.Title</h5>
                    <span class="badge bg-secondary">@recipe.Category</span>
                    @if (recipe.RatingCount > 0)
                    {
                        <span class="ms-2 text-warning">
                            @for (int i = 1; i <= 5; i++)
                            {
                                @(i <= Math.Round(recipe.AverageRating) ? "★" : "☆")
                            }
                            <small class="text-muted">(@recipe.RatingCount)</small>
                        </span>
                    }
                    <p class="card-text mt-2"><strong>Ingredients:</strong> @recipe.Ingredients</p>
                    <a href="recipe/@recipe.Id" class="btn btn-outline-primary btn-sm">View Full Recipe</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter]
    public string? Category { get; set; }

    private IEnumerable<Recipe> GetRecipes() =>
        string.IsNullOrEmpty(Category)
            ? RecipeStore.GetAll()
            : RecipeStore.GetByCategory(Category);
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Models

<PageTitle>@(recipe?.Title ?? "Recipe Not Found")</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="recipes">All Recipes</a></li>
            <li class="breadcrumb-item"><a href="recipes/@recipe.Category.ToLower()">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <div class="card mt-3">
        <div class="card-body">
            <h4>Ingredients</h4>
            <ul>
                @foreach (var ingredient in recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
                {
                    <li>@ingredient</li>
                }
            </ul>
        </div>
    </div>

    <div class="card mt-3">
        <div class="card-body">
            <h4>Steps</h4>
            @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <p>@step</p>
            }
        </div>
    </div>

    <div class="card mt-3">
        <div class="card-body">
            <h4>Rate This Recipe</h4>
            <StarRating RecipeId="recipe.Id" />
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeStore.GetById(Id);
    }
}

@using RecipeCommunity.Models
@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (hoverRating > 0 ? hoverRating : currentRating) ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => hoverRating = star"
              @onmouseout="() => hoverRating = 0"
              style="cursor: pointer; font-size: 1.5rem; color: @(star <= (hoverRating > 0 ? hoverRating : currentRating) ? "#ffc107" : "#dee2e6");">
            ★
        </span>
    }

    @if (hasRated)
    {
        <span class="ms-2 text-success">Thanks for rating!</span>
    }

    @if (recipe?.RatingCount > 0)
    {
        <span class="ms-3 text-muted">
            Average: @recipe.AverageRating.ToString("F1") / 5 (@recipe.RatingCount ratings)
        </span>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int currentRating;
    private int hoverRating;
    private bool hasRated;
    private Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeStore.GetById(RecipeId);
    }

    private void Rate(int stars)
    {
        currentRating = stars;
        hasRated = true;
        RecipeStore.AddRating(RecipeId, stars);
        recipe = RecipeStore.GetById(RecipeId);
    }
}

@page "/submit"
@using RecipeCommunity.Models
@rendermode InteractiveServer

<PageTitle>Submit a Recipe</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Recipe Submitted!</h4>
        <p>Your recipe "<strong>@title</strong>" has been added to the community.</p>
        <a href="recipes" class="btn btn-primary">Browse Recipes</a>
        <button class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="recipeForm">
        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="title" />
            @if (showValidation && string.IsNullOrWhiteSpace(title))
            {
                <div class="text-danger">Title is required.</div>
            }
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="category">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Mexican">Mexican</option>
                <option value="Japanese">Japanese</option>
                <option value="Desserts">Desserts</option>
                <option value="Other">Other</option>
            </InputSelect>
            @if (showValidation && string.IsNullOrWhiteSpace(category))
            {
                <div class="text-danger">Category is required.</div>
            }
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="4" @bind-Value="ingredients"
                           placeholder="Enter ingredients separated by commas" />
            @if (showValidation && string.IsNullOrWhiteSpace(ingredients))
            {
                <div class="text-danger">Ingredients are required.</div>
            }
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="steps"
                           placeholder="Enter each step on a new line" />
            @if (showValidation && string.IsNullOrWhiteSpace(steps))
            {
                <div class="text-danger">Steps are required.</div>
            }
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    private string title = string.Empty;
    private string category = string.Empty;
    private string ingredients = string.Empty;
    private string steps = string.Empty;
    private bool submitted;
    private bool showValidation;

    private void HandleSubmit()
    {
        showValidation = true;

        if (string.IsNullOrWhiteSpace(title) ||
            string.IsNullOrWhiteSpace(category) ||
            string.IsNullOrWhiteSpace(ingredients) ||
            string.IsNullOrWhiteSpace(steps))
        {
            return;
        }

        RecipeStore.AddRecipe(new Recipe
        {
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        });

        submitted = true;
    }

    private void Reset()
    {
        title = string.Empty;
        category = string.Empty;
        ingredients = string.Empty;
        steps = string.Empty;
        submitted = false;
        showValidation = false;
    }
}

