    @foreach (var recipe in GetRecipes())
    {
        <div class="col-md-6 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@recipe.Title</h5>
                    <span class="badge bg-secondary">@recipe.Category</span>
                    @if (recipe.RatingCount > 0)
                    {
                        <span class="ms-2 text-warning">
                            @for (int i = 1; i <= 5; i++)
                            {
                                @(i <= Math.Round(recipe.AverageRating) ? "★" : "☆")
                            }
                            <small class="text-muted">(@recipe.RatingCount)</small>
                        </span>
                    }
                    <p class="card-text mt-2"><strong>Ingredients:</strong> @recipe.Ingredients</p>
                    <a href="recipe/@recipe.Id" class="btn btn-outline-primary btn-sm">View Full Recipe</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter]
    public string? Category { get; set; }

    private IEnumerable<Recipe> GetRecipes() =>
        string.IsNullOrEmpty(Category)
            ? RecipeStore.GetAll()
            : RecipeStore.GetByCategory(Category);
}
"}

